waves.point_eqs_str:
n=sample*6.283;

flip=flip+1;
flip=flip*below(flip,2);

phase=sin(n*3)*sin(n*7.9)*sin(n*16.7)*sin(n*63.5)*6;

xp=sin(n+phase)*flip;
yp=cos(n+phase)*flip;
zp=0;

//rotate on y during draw
ang=n*2+phase*0.2;
xq=xp*sin(ang) + zp*cos(ang);
yq=yp;
zq=xp*cos(ang) - zp*sin(ang);

r1=0.1;g1=0.6;b1=1;
r2=1.0;g2=0.7;b2=0.1;
fade=xq*0.5 + 0.5;
r=r1*fade + r2*(1-fade);
g=g1*fade + g2*(1-fade);
b=b1*fade + b2*(1-fade);

//rotation;
ang=time*0.1;
xp=xq*sin(ang) + zq*cos(ang);
yp=yq;
zp=xq*cos(ang) - zq*sin(ang);

ang=time*0.17;
xq=xp;
yq=yp*sin(ang) + zp*cos(ang);
zq=yp*cos(ang) - zp*sin(ang);


//push into viewspace
zq=zq+3.1;


//project into screenspace
xs=xq/zq;
ys=yq/zq;


x=xs+0.5;
y=ys*1.3+0.5;
a=(1-flip)*0.03*q1;

shapes.frame_eqs_str:
repeats=1;
samplerepeat=0*repeats;
cycle=int(samplerepeat);
sampcyc=samplerepeat - cycle;
cycleto1=cycle/repeats;

n=sampcyc*6.283;
phs=sampcyc;
tm=q1+phs+(cycleto1)*0.1;
tmm=time;
rsample=(1-sampcyc*0.9)*2.2*(cycleto1+1);

//waving
tmc=tm+cycle-phs*0.2;
variation=sin(cycleto1*6.283)*9;
swap=above(sample,0.5)*2-1;
wavex=sin(tmc*(19+variation)*swap)*rsample*0.04;
wavey=cos(tmc*(19+variation)*swap)*rsample*0.04;


xp=sin(tm)*0.4 ;
yp=cos(tm)*0.4 ;

xp=xp*sin(tm*3);
yp=yp*cos(tm*2.6);

xp=xp*sin(tm*0.43);
yp=yp*(cos(tm*1.79)*0.5+0.5);

xp=xp+wavex;
yp=yp+wavey;

x=xp+0.5;
y=-yp*1.333 + 0.5;

